package com.dronefleet.strategy;import com.dronefleet.domain.*;import java.util.*;
public final class BestFitAssignmentStrategy implements AssignmentStrategy{public Optional<Drone> select(List<Drone> ds,AssignmentContext c){return ds.stream().filter(d->d.status()==DroneStatus.AVAILABLE).filter(d->c.requestedType()==null||c.requestedType().equals("Any")||d.type().equals(c.requestedType())).filter(d->d.capacity()>=c.item().weight()).filter(d->d.hasBatteryFor(estimate(d,c.item()))).min(Comparator.comparingDouble((Drone d)->d.capacity()-c.item().weight()).thenComparingInt(Drone::battery));}public String name(){return "BestFitAssignmentStrategy";}private double estimate(Drone d,PackageItem p){return switch(d.type()){case "Heavy"->p.distance()*.6+p.weight()*.25;case "Express"->p.distance()*.55+p.weight()*.2;default->p.distance()*.5+p.weight()*.2;};}}
